from concurrent.futures import ThreadPoolExecutor
import os


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int]) -> int:
    """Return the sum of square(x) for every x in xs.

    Squares are computed in parallel on a thread pool. The result is
    independent of the worker count and of completion order.
    """
    if not xs:
        return 0
    workers = max(1, min(len(xs), os.cpu_count() or 1))
    with ThreadPoolExecutor(max_workers=workers) as pool:
        # executor.map yields results in input order, and integer addition
        # is exact and associative, so the total is deterministic.
        return sum(pool.map(square, xs))


def test_sum_squares_empty() -> None:
    assert sum_squares([]) == 0


def test_sum_squares_single() -> None:
    assert sum_squares([7]) == 49


def test_sum_squares_small() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_sum_squares_negatives() -> None:
    assert sum_squares([-3, 3, -4]) == 9 + 9 + 16


def test_sum_squares_matches_serial_reference() -> None:
    xs = list(range(-500, 501))
    expected = sum(square(x) for x in xs)
    assert sum_squares(xs) == expected


def test_sum_squares_stable_across_repeated_calls() -> None:
    xs = [i * 37 % 1001 - 500 for i in range(5000)]
    expected = sum(square(x) for x in xs)
    results = {sum_squares(xs) for _ in range(20)}
    assert results == {expected}


def test_sum_squares_large_values() -> None:
    xs = [10**6, -(10**6)]
    assert sum_squares(xs) == 2 * 10**12
